import { exactNameCandidates, normalizedTeacherName } from './teacherRoster.js';

export function isAutoGeneratedTeacherCode(code) {
  const value = String(code || '').trim();
  return !value || value.toUpperCase().startsWith('STAFF-');
}

// Decide how each unmatched timetable teacher_code should be handled:
// - create: no existing teacher shares the name; insert a new teacher
// - adopt: exactly one existing teacher shares the name and its code is an
//   auto-generated placeholder, so the timetable abbreviation becomes the code
// - conflicts: zero-code match but the name is ambiguous, or the matched
//   teacher already carries a different real code. Never guess: the caller
//   must surface these for a human decision, because identical names can be
//   different people.
export function resolveTimetableTeachers({ missingCodes, nameByCode, existingTeachers }) {
  const create = [];
  const adopt = [];
  const conflicts = [];
  const adoptedTeacherIds = new Set();

  for (const { teacher_code: code } of missingCodes) {
    const name = String(nameByCode.get(code) || code).trim();
    const candidates = name
      ? exactNameCandidates({ english_name: name, chinese_name: '' }, existingTeachers)
      : [];

    if (candidates.length === 0) {
      create.push({ code, name: name || code });
      continue;
    }

    const available = candidates.filter(candidate => !adoptedTeacherIds.has(candidate.teacher_id));
    if (available.length !== 1) {
      conflicts.push({
        code,
        name,
        reason: available.length === 0 ? 'duplicate-code-mapping' : 'ambiguous-name',
        candidates: candidates.map(candidate => ({
          teacher_id: candidate.teacher_id,
          teacher_code: candidate.teacher_code,
          teacher_name: candidate.teacher_name
        }))
      });
      continue;
    }

    const matched = available[0];
    if (!isAutoGeneratedTeacherCode(matched.teacher_code)) {
      conflicts.push({
        code,
        name,
        reason: 'existing-code-mismatch',
        candidates: [{
          teacher_id: matched.teacher_id,
          teacher_code: matched.teacher_code,
          teacher_name: matched.teacher_name
        }]
      });
      continue;
    }

    adoptedTeacherIds.add(matched.teacher_id);
    adopt.push({ code, teacherId: matched.teacher_id, name: normalizedTeacherName(name) });
  }

  return { create, adopt, conflicts };
}
